# proxmox_nodes.py
import os
import json
from typing import List, Dict, Any

NODES_CONFIG_PATH = os.getenv("PROXMOX_NODES_PATH", "proxmox_nodes.json")

def load_nodes() -> List[Dict[str, Any]]:
    try:
        with open(NODES_CONFIG_PATH, "r") as f:
            config = json.load(f)
        return config.get("nodes", [])
    except FileNotFoundError:
        raise RuntimeError(f"Node config file not found at {NODES_CONFIG_PATH}")
    except json.JSONDecodeError:
        raise RuntimeError(f"Invalid JSON in node config file {NODES_CONFIG_PATH}")
