# proxmox_inventory.py
import requests
from typing import Dict, Any, List
from .proxmox_nodes import load_nodes

class ProxmoxAPIError(Exception):
    pass

class ProxmoxClient:
    def __init__(self, ip: str, username: str, password: str):
        self.base_url = f"https://{ip}:8006/api2/json"
        self.username = username
        self.password = password
        self.ticket = None
        self.csrf = None

    def _get_ticket(self):
        auth_url = f"{self.base_url}/access/ticket"
        payload = {
            "username": self.username,
            "password": self.password
        }
        try:
            response = requests.post(
                auth_url,
                data=payload,
                verify=False  # In production, use proper certificate validation
            )
            response.raise_for_status()
            data = response.json()
            self.ticket = data["data"]["ticket"]
            self.csrf = data["data"]["CSRFPreventionToken"]
        except requests.exceptions.RequestException as e:
            raise ProxmoxAPIError(f"Authentication failed: {e}")

    def _request(self, method: str, endpoint: str, **kwargs):
        if not self.ticket:
            self._get_ticket()
            
        headers = {
            "Cookie": f"PVEAuthCookie={self.ticket}",
            "CSRFPreventionToken": self.csrf
        }
        
        url = f"{self.base_url}{endpoint}"
        try:
            response = requests.request(
                method,
                url,
                headers=headers,
                verify=False,
                **kwargs
            )
            response.raise_for_status()
            return response.json().get("data", [])
        except requests.exceptions.RequestException as e:
            raise ProxmoxAPIError(f"API request failed: {e}")

    def get_version(self) -> str:
        data = self._request("GET", "/version")
        return f"Proxmox VE {data['version']} (API v{data['api_version']})"

    def get_system_status(self) -> Dict[str, str]:
        data = self._request("GET", "/nodes/self/status")
        return {
            "cpu": f"{data['cpu']}%",
            "ram": f"{data['mem']/1024**3:.1f}GB",
            "swap": f"{data['swap']/1024**3:.1f}GB"
        }

    def get_storage(self) -> Dict[str, str]:
        data = self._request("GET", "/storage")
        return {
            storage["storage"]: f"{storage['total']/1024**3:.1f}GB"
            for storage in data
        }

    def get_vms(self) -> List[Dict[str, str]]:
        data = self._request("GET", "/nodes/self/qemu")
        return [
            {"id": vm["vmid"], "name": vm["name"]}
            for vm in data
        ]

    def get_containers(self) -> List[Dict[str, str]]:
        data = self._request("GET", "/nodes/self/lxc")
        return [
            {"id": ct["vmid"], "name": ct["name"]}
            for ct in data
        ]

    def get_networks(self) -> Dict[str, str]:
        data = self._request("GET", "/nodes/self/network")
        return {
            interface["iface"]: interface.get("ip", "N/A")
            for interface in data
        }

    def get_disk_health(self) -> Dict[str, str]:
        # Proxmox API doesn't expose SMART data directly
        # This would require SSH access or alternative method
        return {"note": "SMART data not available via API"}

def collect_inventory() -> Dict[str, Any]:
    nodes = load_nodes()
    inventory = {}
    
    for node in nodes:
        try:
            client = ProxmoxClient(
                ip=node["ip"],
                username=node["username"],
                password=node["password"]
            )
            
            inventory[node["name"]] = {
                "version": client.get_version(),
                **client.get_system_status(),
                "storage": client.get_storage(),
                "vms": client.get_vms(),
                "containers": client.get_containers(),
                "networks": client.get_networks(),
                "disk_health": client.get_disk_health()
            }
        except ProxmoxAPIError as e:
            inventory[node["name"]] = {"error": str(e)}
    
    return inventory
