# topology_generator.py
import os
from jinja2 import Template
from typing import Dict, Any

TOPOLOGY_TEMPLATE = """# Proxmox Cluster Inventory

## Node Summary
{% for node_name, data in inventory.items() %}
- {{ node_name }}
  - Version: {{ data.version }}
  - CPU: {{ data.cpu }}
  - RAM: {{ data.ram }}
  - Storage: {{ data.storage|join(', ') }}
  - VMs: {{ data.vms|length }}
  - Containers: {{ data.containers|length }}
  - Networks: {{ data.networks|join(', ') }}
{% endfor %}

## Topology Diagram

```mermaid
graph TD
{% for node_name, data in inventory.items() %}
    {{ node_name|replace(' ', '') }}["{{ node_name }}"]
    {% for vm in data.vms %}
    {{ node_name|replace(' ', '') }} --> {{ node_name|replace(' ', '') }}VM{{ vm.id }}["VM{{ vm.id }}: {{ vm.name }}"]
    {% endfor %}
    {% for ct in data.containers %}
    {{ node_name|replace(' ', '') }} --> {{ node_name|replace(' ', '') }}CT{{ ct.id }}["CT{{ ct.id }}: {{ ct.name }}"]
    {% endfor %}
    {% for storage_name in data.storage %}
    {{ node_name|replace(' ', '') }} --> {{ node_name|replace(' ', '') }}ST{{ storage_name|replace(' ', '') }}["Storage: {{ storage_name }}"]
    {% endfor %}
{% endfor %}
```
"""

OUTPUT_PATH = os.getenv("INVENTORY_OUTPUT_PATH", "reports/proxmox_inventory.md")

def generate_topology(inventory: Dict[str, Any]):
    template = Template(TOPOLOGY_TEMPLATE)
    content = template.render(inventory=inventory)
    
    os.makedirs(os.path.dirname(OUTPUT_PATH), exist_ok=True)
    with open(OUTPUT_PATH, "w") as f:
        f.write(content)
    
    return OUTPUT_PATH
