# test_proxmox_inventory.py
import pytest
from unittest.mock import patch, MagicMock
from proxmox_inventory import ProxmoxClient, collect_inventory
from proxmox_nodes import load_nodes

@pytest.fixture
def mock_nodes():
    return [
        {
            "name": "Test Node",
            "ip": "127.0.0.1",
            "username": "test@pam",
            "password": "testpass",
            "role": "test"
        }
    ]

def test_load_nodes():
    with patch("builtins.open", unittest.mock.mock_open(read_data='{"nodes": []}')):
        nodes = load_nodes()
        assert isinstance(nodes, list)

def test_proxmox_client_auth():
    mock_client = MagicMock()
    mock_client.return_value = {"data": {"ticket": "123", "CSRFPreventionToken": "abc"}}
    
    with patch("requests.post", mock_client):
        client = ProxmoxClient("127.0.0.1", "user", "pass")
        client._get_ticket()
        assert client.ticket == "123"
        assert client.csrf == "abc"

def test_proxmox_client_get_version():
    mock_client = MagicMock()
    mock_client._request.return_value = {
        "data": {
            "version": "8.0-1",
            "api_version": "2.0"
        }
    }
    
    version = mock_client.get_version()
    assert version == "Proxmox VE 8.0-1 (API v2.0)"

def test_collect_inventory(mock_nodes):
    with patch("proxmox_nodes.load_nodes", return_value=mock_nodes):
        with patch("proxmox_inventory.ProxmoxClient", autospec=True) as mock_client:
            mock_client.return_value.get_version.return_value = "Test Version"
            inventory = collect_inventory()
            assert "Test Node" in inventory
            assert "version" in inventory["Test Node"]
